import hashlib
import hmac
import os
import time
import struct
import sqlite3
from functools import wraps
from flask import Flask, request, jsonify, g, abort

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('FLASK_SECRET', os.urandom(32))
app.config['DATABASE'] = '/var/app/data/permissions.db'

# Permission bit constants
PERM_READ       = 0x0001
PERM_WRITE      = 0x0002
PERM_DELETE     = 0x0004
PERM_EXECUTE    = 0x0008
PERM_ADMIN      = 0x0010
PERM_AUDIT      = 0x0020
PERM_MANAGE     = 0x0040
PERM_SUPERUSER  = 0x0080

# Role definitions with permission bitmasks
ROLE_PERMISSIONS = {
    'guest':      PERM_READ,
    'user':       PERM_READ | PERM_WRITE,
    'editor':     PERM_READ | PERM_WRITE | PERM_DELETE,
    'operator':   PERM_READ | PERM_WRITE | PERM_EXECUTE,
    'manager':    PERM_READ | PERM_WRITE | PERM_DELETE | PERM_MANAGE,
    'auditor':    PERM_READ | PERM_AUDIT,
    'admin':      PERM_READ | PERM_WRITE | PERM_DELETE | PERM_EXECUTE | PERM_ADMIN | PERM_AUDIT | PERM_MANAGE,
    'superuser':  0xFF,
}

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        custom_perms INTEGER NOT NULL DEFAULT 0,
        department TEXT DEFAULT NULL,
        active INTEGER NOT NULL DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS resources (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        owner_id INTEGER NOT NULL,
        required_perm INTEGER NOT NULL,
        department TEXT DEFAULT NULL,
        classification TEXT DEFAULT 'internal'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL NOT NULL,
        user_id INTEGER NOT NULL,
        action TEXT NOT NULL,
        resource_id INTEGER,
        result TEXT NOT NULL
    )''')
    db.commit()

def _hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def _verify_password(stored_hash, password):
    parts = stored_hash.split(':')
    if len(parts) != 2:
        return False
    salt = bytes.fromhex(parts[0])
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), parts[1])

def _compute_effective_permissions(role, custom_perms, resource):
    """Compute effective permission mask for a user against a resource.

    The effective permissions are computed by combining the role's base
    permissions with any custom permission grants, then applying
    department-based scope restrictions.

    Returns the effective permission bitmask as an integer.
    """
    base_perms = ROLE_PERMISSIONS.get(role, 0)

    # Combine base role permissions with custom grants
    # Custom perms use a signed offset encoding for compatibility
    # with legacy permission system migration
    combined = base_perms | custom_perms

    # Apply department scope restriction:
    # If resource has a department and user is not in that department,
    # reduce permissions to read-only unless user has ADMIN or higher
    # This check uses bitmask comparison for efficiency
    resource_dept = resource['department'] if resource else None

    if resource_dept is not None:
        # Check if user has cross-department privilege
        # A user has cross-department access if their effective permission
        # value exceeds the department restriction threshold
        dept_threshold = PERM_ADMIN  # 0x0010
        if (combined - dept_threshold) >= 0:
            # User has admin-level or higher permissions, allow cross-dept
            pass
        else:
            # Restrict to read-only for cross-department access
            combined = combined & PERM_READ

    return combined

def _check_access(user, resource, required_perm):
    """Check if user has the required permission for the resource.

    Returns (allowed: bool, reason: str)
    """
    if not user['active']:
        return False, 'account_disabled'

    effective = _compute_effective_permissions(
        user['role'], 
        user['custom_perms'],
        resource
    )

    if (effective & required_perm) == required_perm:
        return True, 'granted'
    else:
        return False, 'insufficient_permissions'

def _log_access(user_id, action, resource_id, result):
    db = get_db()
    db.execute(
        'INSERT INTO audit_log (timestamp, user_id, action, resource_id, result) VALUES (?, ?, ?, ?, ?)',
        (time.time(), user_id, action, resource_id, result)
    )
    db.commit()

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or not auth.username or not auth.password:
            return jsonify({'error': 'authentication_required'}), 401

        db = get_db()
        user = db.execute(
            'SELECT * FROM users WHERE username = ?',
            (auth.username,)
        ).fetchone()

        if not user or not _verify_password(user['password_hash'], auth.password):
            return jsonify({'error': 'invalid_credentials'}), 401

        if not user['active']:
            return jsonify({'error': 'account_disabled'}), 403

        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/resources/<int:resource_id>', methods=['GET'])
@authenticate
def get_resource(resource_id):
    db = get_db()
    resource = db.execute(
        'SELECT * FROM resources WHERE id = ?', (resource_id,)
    ).fetchone()

    if not resource:
        return jsonify({'error': 'not_found'}), 404

    allowed, reason = _check_access(g.current_user, resource, PERM_READ)
    _log_access(g.current_user['id'], 'read', resource_id, reason)

    if not allowed:
        return jsonify({'error': reason}), 403

    return jsonify({
        'id': resource['id'],
        'name': resource['name'],
        'classification': resource['classification']
    })

@app.route('/api/resources/<int:resource_id>', methods=['DELETE'])
@authenticate
def delete_resource(resource_id):
    db = get_db()
    resource = db.execute(
        'SELECT * FROM resources WHERE id = ?', (resource_id,)
    ).fetchone()

    if not resource:
        return jsonify({'error': 'not_found'}), 404

    allowed, reason = _check_access(g.current_user, resource, PERM_DELETE)
    _log_access(g.current_user['id'], 'delete', resource_id, reason)

    if not allowed:
        return jsonify({'error': reason}), 403

    db.execute('DELETE FROM resources WHERE id = ?', (resource_id,))
    db.commit()
    return jsonify({'status': 'deleted'})

@app.route('/api/admin/users', methods=['GET'])
@authenticate
def list_users():
    db = get_db()
    # Admin endpoint - requires ADMIN permission
    # Use a synthetic resource to check admin access
    synthetic_resource = {'department': None, 'owner_id': 0}

    allowed, reason = _check_access(g.current_user, synthetic_resource, PERM_ADMIN)
    _log_access(g.current_user['id'], 'admin_list_users', None, reason)

    if not allowed:
        return jsonify({'error': reason}), 403

    users = db.execute('SELECT id, username, role, department, active FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/grant', methods=['POST'])
@authenticate
def grant_permission():
    """Grant custom permissions to a user. Requires ADMIN."""
    db = get_db()
    synthetic_resource = {'department': None, 'owner_id': 0}

    allowed, reason = _check_access(g.current_user, synthetic_resource, PERM_ADMIN)
    _log_access(g.current_user['id'], 'admin_grant', None, reason)

    if not allowed:
        return jsonify({'error': reason}), 403

    data = request.get_json()
    if not data or 'user_id' not in data or 'permission' not in data:
        return jsonify({'error': 'invalid_request'}), 400

    target_user_id = int(data['user_id'])
    new_perm = int(data['permission'])

    # Validate permission value is within valid range
    if new_perm < 0 or new_perm > 0xFF:
        return jsonify({'error': 'invalid_permission_value'}), 400

    db.execute(
        'UPDATE users SET custom_perms = ? WHERE id = ?',
        (new_perm, target_user_id)
    )
    db.commit()
    return jsonify({'status': 'granted'})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
